public final class StaticModelHarnessPolicy: InvocablePolicy {
    public typealias State = StaticModelHarnessState
    public typealias Event = StaticModelHarnessEvent


    /// W3C SCXML 5.10: this session's id, `_sessionid`. A host that has one for
    /// it gives it before it starts the machine; a child's is its parent's and
    /// the id it was started under (docs/adr/0045).
    public var sessionID: String

    /// W3C SCXML 6.4: the queue the invoking parent installs, whose presence is
    /// the link to it. Unbounded; see `ParentEventQueue`.
    public var parentEventQueue: ParentEventQueue?

    // The typed `_event.data` of the event being processed, bound by the policy's
    // `populateEventMetadata` or lifted by `liftTypedPayload`.
    var pendingPayloadTag: StaticModelHarnessPayloadTag = .none
    var pendingDoneInvokeGenPayload = StaticModelHarnessDoneInvokeGenPayload()
    var pendingHarnessOfferPayload = StaticModelHarnessHarnessOfferPayload()
    var pendingHarnessStartPayload = StaticModelHarnessHarnessStartPayload()


    // ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
    /// W3C SCXML 5.2: the `offered` datamodel variable, published (`sce:direction="out"`).
    var vOffered: [UInt32] = []
    /// W3C SCXML 5.2: the `request` datamodel variable.
    var vRequest: String = ""
    /// W3C SCXML 5.2: the `prompt` datamodel variable.
    var vPrompt: String = ""
    /// W3C SCXML 5.2: the `said` datamodel variable.
    var vSaid: String = ""
    /// W3C SCXML 5.2: the `offered_ok` datamodel variable.
    var vOfferedOk: Bool = false
    /// W3C SCXML 5.2: the `refused` datamodel variable.
    var vRefused: StaticModelHarnessRefusalRecord = StaticModelHarnessRefusalRecord(code: StaticModelHarnessHarnessCodeEnum.notJson, path: "")
    /// W3C SCXML 5.2: the `refusals` datamodel variable, published (`sce:direction="out"`).
    var vRefusals: [StaticModelHarnessRefusalRecord] = []
    /// W3C SCXML 5.2: the `attempts` datamodel variable, published (`sce:direction="out"`).
    var vAttempts: UInt32 = 0
    /// W3C SCXML 5.2: the `outcome` datamodel variable, published (`sce:direction="out"`).
    var vOutcome: String = ""
    /// W3C SCXML 5.2: the `answer` datamodel variable, published (`sce:direction="out"`).
    var vAnswer: StaticModelHarnessAnswerRecord? = nil
    /// W3C SCXML 5.2: the `why` datamodel variable, published (`sce:direction="out"`).
    var vWhy: StaticModelHarnessLiftRefusalRecord? = nil

    /// Reports what the published `offered` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var offered: [UInt32] { vOffered }

    /// Reports what the published `refusals` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var refusals: [StaticModelHarnessRefusalRecord] { vRefusals }

    /// Reports what the published `attempts` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var attempts: UInt32 { vAttempts }

    /// Reports what the published `outcome` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var outcome: String { vOutcome }

    /// Reports what the published `answer` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var answer: StaticModelHarnessAnswerRecord? { vAnswer }

    /// Reports what the published `why` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var why: StaticModelHarnessLiftRefusalRecord? { vWhy }

    /// W3C SCXML 6.4.1: the values a parent's `<param>` and `namelist` give this
    /// machine's variables before it starts, each in the slot named as its
    /// variable's property is. A slot left `nil` keeps the value its `<data>` gave
    /// it; a variable that may be absent is handed the optional value whole.
    public struct InvokeParams {
        public init() {}
        public var vRequest: String? = nil
        public var vPrompt: String? = nil
        public var vSaid: String? = nil
        public var vOfferedOk: Bool? = nil
        public var vAttempts: UInt32? = nil
        public var vOutcome: String? = nil
    }

    /// Gives this machine the values `params` carries, in place of the ones its
    /// `<data>` gave. Called before the machine starts.
    public func acceptParams(_ params: InvokeParams) {
        if let value = params.vRequest {
            vRequest = value
        }
        if let value = params.vPrompt {
            vPrompt = value
        }
        if let value = params.vSaid {
            vSaid = value
        }
        if let value = params.vOfferedOk {
            vOfferedOk = value
        }
        if let value = params.vAttempts {
            vAttempts = value
        }
        if let value = params.vOutcome {
            vOutcome = value
        }
    }

    public init() {
        sessionID = drawSessionID()
    }

    /// Gives this session the id its host has for it, in place of the one it
    /// drew: an XML Nmtoken, since another session addresses this one as
    /// `#_scxml_<id>` and every child's id is this one's and the id the child was
    /// started under (docs/adr/0045). Refused for anything else.
    public func setSessionID(_ id: String) throws {
        let reason = sessionIDRefusalOf(id)
        if !reason.isEmpty {
            throw SendArgumentError(reason)
        }
        sessionID = id
    }

    // ------------------------------------------------------------------
    // Delivery to the parent (W3C SCXML 6.2 + 6.4)
    // ------------------------------------------------------------------

    /// Delivers a delayed `<send target="#_parent">` whose wait is over, with the
    /// payload an immediate one carries (W3C SCXML 6.2 + 6.4). It waited in this
    /// machine's own queue, so `<cancel>` reached it and a child that ended first
    /// dropped it: the engine dispatches nothing once final. Emitted for every
    /// machine, since the one that needs it is an invoked child, which need not
    /// invoke anything itself.
    public func deliverToParent(eventName: String, eventData: String) -> Bool {
        guard let parentEventQueue else {
            return false
        }
        parentEventQueue.push(ParentEvent(name: eventName, data: eventData))
        return true
    }

    /// Whether a session invoked this one (W3C SCXML C.1): the queue the invoking
    /// parent installs is the link to it.
    public var hasParentSession: Bool {
        parentEventQueue != nil
    }

    /// Whether `sessionID` names the session that invoked this one (W3C SCXML C.1). The
    /// location a session publishes is a target, so a reply sent to the origin of an
    /// event the parent sent, its location, reaches the parent as `#_parent` does
    /// (docs/adr/0090). The queue the parent installed knows who installed it.
    public func isParentSession(_ sessionID: String) -> Bool {
        guard let parentEventQueue, !sessionID.isEmpty else {
            return false
        }
        return parentEventQueue.parentSessionID.utf8.elementsEqual(sessionID.utf8)
    }

    // ======================================================================
    // StatePolicy implementation
    // ======================================================================

    /// The initial state (W3C SCXML 3.3).
    public func initialState() -> StaticModelHarnessState {
        .waiting
    }

    /// Whether `state` is a `<final>` state (W3C SCXML 3.7).
    public func isFinalState(_ state: StaticModelHarnessState) -> Bool {
        switch state {
        case .accepted:
            return true
        case .gaveUp:
            return true
        default:
            return false
        }
    }

    /// The parent of `state`; nil at the root (W3C SCXML 3.3).
    public func getParent(_ state: StaticModelHarnessState) -> StaticModelHarnessState? {
        switch state {
        case .accepted:
            return .harness
        case .check:
            return .work
        case .compose:
            return .work
        case .gaveUp:
            return .harness
        case .generate:
            return .work
        case .repair:
            return .work
        case .retry:
            return .work
        case .waiting:
            return .harness
        case .work:
            return .harness
        default:
            return nil
        }
    }

    /// Whether `state` is a `<state>` with child states: exactly the states that
    /// have an initial transition. A `<parallel>` is not compound (W3C SCXML 3.3).
    public func isCompoundState(_ state: StaticModelHarnessState) -> Bool {
