    }

    public func isParallelState(_ state: StaticModelHarnessState) -> Bool { false }

    /// `state`'s `<state>`, `<parallel>` and `<final>` children, in document
    /// order; for a `<parallel>`, its regions (§scxml-D-getChildStates).
    public func getChildStates(_ state: StaticModelHarnessState) -> [StaticModelHarnessState] {
