    }

    // W3C SCXML 3.10: this document declares no <history>, so no target list names
    // one and the engine never asks the two below; answering would mean inventing
    // one.
    public func getHistoryParent(_ history: HistoryID) -> StaticModelHarnessState {
        preconditionFailure("StaticModelHarnessPolicy declares no <history>; asked for \(history)")
