    public var hasActiveStates: Bool { false }

    public var hasParallelStates: Bool { false }
    public var needsScriptEngine: Bool { false }
    public var needsDataModelInit: Bool { false }
    public var hasInvokeSupport: Bool { true }
    public var hasChildTick: Bool { false }
