    public var needsParent: Bool { false }

    /// The `<invoke>`s a host runs (W3C SCXML 6.4.1): their `done.invoke.<id>` is
    /// accepted only through the engine's `completeHostInvoke`.
    public var hostInvokeIDs: [String] { ["gen"] }
    public var hasFinalize: Bool { false }
    public var hasAutoforward: Bool { false }

    /// W3C SCXML 5.10: `_event` is bound by the policy's guards, and this
    /// document's guards never read it, so there is nothing to bind.
    public func bindCurrentEvent(_ event: StaticModelHarnessEvent, engine: Engine<StaticModelHarnessPolicy>) {}

    /// Binds the typed `_event.data` view an inject seam carried (§scxml-5.10).
    public func populateEventMetadata(_ metadata: EventMetadata) {
        pendingPayloadTag = .none
        switch metadata.typedPayload {
        case let payload as StaticModelHarnessDoneInvokeGenPayload:
            pendingPayloadTag = .doneInvokeGen
            pendingDoneInvokeGenPayload = payload
        case let payload as StaticModelHarnessHarnessOfferPayload:
            pendingPayloadTag = .harnessOffer
            pendingHarnessOfferPayload = payload
        case let payload as StaticModelHarnessHarnessStartPayload:
            pendingPayloadTag = .harnessStart
            pendingHarnessStartPayload = payload
        default:
            break
        }
    }


    /// Reads the typed `_event.data` view out of the data every other producer
    /// carries, and refuses what the schema does not admit (§scxml-3.13).
    public func liftTypedPayload(event: StaticModelHarnessEvent, metadata: EventMetadata) throws {
        // A typed carrier already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if pendingPayloadTag != .none {
            return
        }
        switch event {
        case .doneInvokeGen:
            let fields = try PayloadFields.decode(metadata.data)
            var payload = StaticModelHarnessDoneInvokeGenPayload()
            payload.error = try fields.text("error")
            payload.text = try fields.text("text")
            payload.constrained = try fields.truth("constrained")
            payload.model = try fields.text("model")
            payload.prompt_tokens = try fields.unsigned("prompt_tokens")
            payload.answer_tokens = try fields.unsigned("answer_tokens")
            payload.finish = try fields.text("finish")
            pendingDoneInvokeGenPayload = payload
            pendingPayloadTag = .doneInvokeGen
        case .harnessOffer:
            let fields = try PayloadFields.decode(metadata.data)
            var payload = StaticModelHarnessHarnessOfferPayload()
            payload.id = try fields.unsigned("id")
            pendingHarnessOfferPayload = payload
            pendingPayloadTag = .harnessOffer
        case .harnessStart:
            let fields = try PayloadFields.decode(metadata.data)
            var payload = StaticModelHarnessHarnessStartPayload()
            payload.request = try fields.text("request")
            pendingHarnessStartPayload = payload
            pendingPayloadTag = .harnessStart
        default:
            break
        }
    }


    /// Forgets the typed view once the event's transition has been processed.
    public func clearEventMetadata() {
        pendingPayloadTag = .none
    }




    // ------------------------------------------------------------------
    // Host invocations (W3C SCXML 6.4)
    // ------------------------------------------------------------------

    /// W3C SCXML 6.4: the `<invoke>`s a state's entry deferred to the end of the
    /// macrostep. A state exited before then drops its own.
    private var pendingInvokes: [PendingInvoke<StaticModelHarnessState>] = []

    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<StaticModelHarnessPolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("gen".utf8) {
                sceStartHostInvokeGen(engine: engine)
                return
            }
        }
    }

    /// Starts `<invoke type="sce-host-model-generate" id="gen">`
    /// (W3C SCXML 6.4.1): the invoker the host registered for the type is handed the
    /// request, under the id the DOCUMENT wrote, which is the name `done.invoke.<id>`
    /// carries. A type the host declared and never registered an invoker for is the same
    /// fact as an unsupported one, so the same event, and not a silence that reads as
    /// started.
    private func sceStartHostInvokeGen(engine: Engine<StaticModelHarnessPolicy>) {
        // W3C SCXML 6.4.1: what the request says is evaluated now, when the invocation
        // starts. The text the host reads is the one each value spells; the JSON is the
        // typed pairs, written once, so a host that forwards the request forwards the
        // engine's serialisation. A value that cannot be evaluated starts nothing.
        var hostParams: [String: [String]] = [:]
        var hostParts: [PayloadPair] = []
        do {
            let sceValue: WireValue = .text(self.vPrompt)
            appendFormParam(&hostParams, "prompt", sceValue)
            hostParts.append(PayloadPair("prompt", sceValue))
        }
        do {
            let sceValue: WireValue = .integer(Int64(256))
            appendFormParam(&hostParams, "max_tokens", sceValue)
            hostParts.append(PayloadPair("max_tokens", sceValue))
        }
        do {
            let sceValue: WireValue = .integer(Int64(0))
            appendFormParam(&hostParams, "temperature_milli", sceValue)
            hostParts.append(PayloadPair("temperature_milli", sceValue))
        }
        do {
            let sceValue: WireValue = .integer(Int64(8000))
            appendFormParam(&hostParams, "_sce_deadline_ms", sceValue)
            hostParts.append(PayloadPair("_sce_deadline_ms", sceValue))
        }
        appendFormParam(&hostParams, "answer_schema", .text("urn:sce:schema:lift_answer:2"))
        hostParts.append(PayloadPair("answer_schema", .text("urn:sce:schema:lift_answer:2")))
        let request = HostInvokeRequest(
            processorType: "sce-host-model-generate",
            invokeID: "gen",
            params: hostParams,
            eventData: hostParts.isEmpty ? "" : payloadJSON(hostParts),
            sessionID: sessionID
        )
        if !engine.performHostInvoke(request) {
            engine.raise(EventWithMetadata.platformError(StaticModelHarnessEvent.errorExecution, message: "<invoke> names an invoker the host declared but never registered"))
        }
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: StaticModelHarnessState, engine: Engine<StaticModelHarnessPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .accepted:
            // W3C SCXML 3.7: Final state reached; raise done.state.harness
            engine.raise(EventWithMetadata(StaticModelHarnessEvent.doneStateHarness))
        case .check:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
            sceBlock: do {


                self.vOfferedOk = false


                if (self.vAnswer != nil) {

                // W3C SCXML 4.6: <foreach array="offered" item="offer">, a native loop over a sce-static list
                for offer in self.vOffered {
                    _ = offer

                if (offer == SceOptional.proven(self.vAnswer).id) {


                self.vOfferedOk = true

                }

                }
                }

            }
        case .compose:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
