extension Engine where Policy == StaticModelHarnessPolicy {
    /// Raises `harness.offer` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseHarnessOffer(id: UInt32) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticModelHarnessEvent.harnessOffer,
                metadata: EventMetadata(
                    data: payloadJSON(.integer("id", id)),
                    eventType: .externalEvent,
                    typedPayload: StaticModelHarnessHarnessOfferPayload(id: id)
                )
            )
        )
    }

    /// Raises `harness.start` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseHarnessStart(request: String) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticModelHarnessEvent.harnessStart,
                metadata: EventMetadata(
                    data: payloadJSON(.text("request", request)),
                    eventType: .externalEvent,
                    typedPayload: StaticModelHarnessHarnessStartPayload(request: request)
                )
            )
        )
    }
}


/// `sce:request`: the record the host is asked to start `<invoke id="gen">`
/// with (SCE Accepted Subset §2.12).
public struct StaticModelHarnessGenRequest: Equatable, Sendable {
    public var prompt: String
    public var answer_schema: String
    public var max_tokens: UInt32
    public var temperature_milli: UInt16

    public init(prompt: String, answer_schema: String, max_tokens: UInt32, temperature_milli: UInt16) {
        self.prompt = prompt
        self.answer_schema = answer_schema
        self.max_tokens = max_tokens
        self.temperature_milli = temperature_milli
    }
}

/// `sce:result`: the record the host completes `<invoke id="gen">`
/// with (SCE Accepted Subset §2.12).
public struct StaticModelHarnessGenResult: Equatable, Sendable {
    public var error: String
    public var text: String
    public var constrained: Bool
    public var model: String
    public var prompt_tokens: UInt32
    public var answer_tokens: UInt32
    public var finish: String

    public init(error: String, text: String, constrained: Bool, model: String, prompt_tokens: UInt32, answer_tokens: UInt32, finish: String) {
        self.error = error
        self.text = text
        self.constrained = constrained
        self.model = model
        self.prompt_tokens = prompt_tokens
        self.answer_tokens = answer_tokens
        self.finish = finish
    }

    /// The JSON `done.invoke.gen` carries this record as, in the schema's order.
    public var wire: String {
        payloadJSON(.text("error", error), .text("text", text), .truth("constrained", constrained), .text("model", model), .integer("prompt_tokens", prompt_tokens), .integer("answer_tokens", answer_tokens), .text("finish", finish))
    }
}

