}

/// Registers `invoker` as the handler for `type="sce-host-model-generate"`.
public func registerStaticModelHarnessSceHostModelGenerateInvoker(on engine: Engine<StaticModelHarnessPolicy>, invoker: StaticModelHarnessSceHostModelGenerateInvoker) throws(HostRegistrationError) {
    try engine.registerInvoker("sce-host-model-generate") { event in
        switch event {
        case .start(let start):
            if start.invokeID.utf8.elementsEqual("gen".utf8) {
                let typed = StaticModelHarnessGenRequest(prompt: start.requestString("prompt"), answer_schema: start.requestString("answer_schema"), max_tokens: start.requestInteger("max_tokens", as: UInt32.self), temperature_milli: start.requestInteger("temperature_milli", as: UInt16.self))
                if let result = invoker.startGen(typed, token: start.token) {
                    return .done(result.wire)
                }
                return nil
            }
            return nil
        case .cancel(let cancel):
            if cancel.invokeID.utf8.elementsEqual("gen".utf8) {
                invoker.cancelGen(token: cancel.token)
                return nil
            }
            return nil
        }
    }
}

/// Completes `<invoke id="gen">`'s start `token` with its record:
/// `completeHostInvoke` with the record's JSON, so a stale or unknown token is
/// refused the same way (false).
@discardableResult
public func completeStaticModelHarnessGen(on engine: Engine<StaticModelHarnessPolicy>, token: UInt64, result: StaticModelHarnessGenResult) -> Bool {
    engine.completeHostInvoke(processorType: "sce-host-model-generate", invokeID: "gen", token: token, doneData: result.wire)
}


